import { z } from "zod";
import type { EditPlan } from "../edit/types";

export const FLOWS = ["google-flow", "veoframe", "higgsfield", "fal"] as const;
export type FlowId = (typeof FLOWS)[number];

export const ClipSchema = z.object({
  id: z.string().regex(/^[a-z0-9-]+$/, "clip id must be lowercase letters, digits or dashes"),
  /** ai_video: generated by a video model (8 s). still_kenburns: an image with slow motion. card: a text card. */
  type: z.enum(["ai_video", "still_kenburns", "card"]).default("ai_video"),
  /** Planned on-screen length. AI clips are 8 seconds and are trimmed to this length. */
  seconds: z.number().min(2).max(60).default(8),
  /** Seconds to skip at the start of the generated clip (for example a slow first moment). */
  trimStart: z.number().min(0).max(3).default(0),
  purpose: z.string().optional(),
  /** The full prompt sent to the video model (ai_video only). Must include the style bible. */
  prompt: z.string().default(""),
  /** What the narrator says while this clip is on screen. */
  narration: z.string().default(""),
  /** Words shown as captions when they differ from the spoken words (Urdu and Hindi: the Roman transliteration). */
  captionText: z.string().optional(),
  /** Voice of this clip's speaker (a character's own voice); the plan's narration voice when absent. */
  voice: z.string().optional(),
  referenceImage: z.string().optional(),
  /**
   * "previous": this clip is generated from the LAST FRAME of the clip before it (attach that frame as the start
   * frame), so the two shots join without a visible jump. Use it for every clip after the first in a story that
   * should feel like one continuous shot; the prompt then describes the camera continuing from where it stopped.
   */
  continuesFrom: z.literal("previous").optional(),
  /** still_kenburns: image path (absolute, or relative to the project's run folder). */
  image: z.string().optional(),
  /** card: the text shown. */
  text: z.string().max(240).optional(),
});

const NarrationSchema = z.object({
  mode: z.enum(["tts", "veo-native", "none"]).default("tts"),
  model: z.string().default("gpt-4o-mini-tts"),
  voice: z.string().default("onyx"),
  instructions: z.string().default("Calm, confident documentary narrator. Clear and unhurried, slight awe, no filler."),
  /** Seconds of silence before narration starts inside each clip. */
  delay: z.number().min(0).max(1.5).default(0.25),
  /** Narration playback speed for tts-1 models, 0.8 to 1.3. */
  speed: z.number().min(0.8).max(1.3).default(1.0),
});

const CaptionsSchema = z.object({
  enabled: z.boolean().default(true),
  wordsPerChunk: z.number().min(1).max(5).default(3),
  /** Animation: classic (spoken word turns gold), pop (words pop in one by one), karaoke (gold fill sweep), slam (one big word). */
  style: z.enum(["classic", "pop", "karaoke", "slam"]).default("classic"),
  /** Defaults: 92 for 9:16, 60 for 16:9. */
  fontSize: z.number().optional(),
  /** Distance from the bottom edge in pixels; keeps text clear of the Shorts interface. Defaults: 672 for 9:16 (caption bottom edge at y 1248), 110 for 16:9. */
  marginBottom: z.number().optional(),
});

export const ShortPlanSchema = z
  .object({
    id: z.string().regex(/^[a-z0-9-]+$/),
    niche: z.string(),
    topic: z.string(),
    title: z.string().min(5),
    language: z.string().default("en"),
    flow: z.enum(FLOWS).default("google-flow"),
    format: z.enum(["short", "long"]).default("short"),
    aspect: z.enum(["9:16", "16:9"]).default("9:16"),
    targetSeconds: z.number().min(15).max(3600).default(32),
    hook: z.object({ type: z.string(), line: z.string(), visual: z.string() }),
    /** One sentence repeated in every clip prompt so all clips share a look. */
    styleBible: z.string().min(20),
    clips: z.array(ClipSchema).min(2).max(400),
    narration: NarrationSchema.default(() => NarrationSchema.parse({})),
    ambientGain: z.number().min(0).max(1).default(0.22),
    /** Optional background music file (absolute path). Mixed quietly and ducked under the narration. */
    music: z.object({ file: z.string(), gain: z.number().min(0).max(0.5).default(0.12) }).optional(),
    captions: CaptionsSchema.default(() => CaptionsSchema.parse({})),
    /** Long-form chapters: each starts at the given clip. */
    chapters: z.array(z.object({ title: z.string().min(2).max(80), clipId: z.string() })).default([]),
    facts: z.array(z.object({ claim: z.string(), source: z.string() })).default([]),
    /** Optional edit decision list (src/edit). Old plans have none and are assembled exactly as before. */
    edit: z.custom<EditPlan>((v) => v == null || (typeof v === "object" && (v as { version?: number }).version === 1)).optional(),
    description: z.string().default(""),
    tags: z.array(z.string()).default([]),
  })
  .superRefine((p, ctx) => {
    const bad = (path: (string | number)[], message: string) => ctx.addIssue({ code: "custom", path, message });
    if (p.format === "short") {
      if (p.aspect !== "9:16") bad(["aspect"], "a Short must be 9:16");
      if (p.targetSeconds > 60) bad(["targetSeconds"], "a Short plan must be 60 seconds or less");
      if (p.clips.length > 8) bad(["clips"], "a Short plan can have at most 8 clips");
    } else if (p.aspect !== "16:9") {
      bad(["aspect"], "a long-form video must be 16:9");
    }
    p.clips.forEach((c, i) => {
      if (c.type === "ai_video") {
        if (c.prompt.trim().length < 40) bad(["clips", i, "prompt"], "an AI clip needs a prompt of at least 40 characters");
        if (c.seconds > 8) bad(["clips", i, "seconds"], "an AI clip is at most 8 seconds");
      }
      if (c.type === "still_kenburns" && !c.image) bad(["clips", i, "image"], "a still clip needs an image path");
      if (c.type === "card" && !c.text) bad(["clips", i, "text"], "a card clip needs text");
    });
    const ids = new Set<string>();
    p.clips.forEach((c, i) => {
      if (ids.has(c.id)) bad(["clips", i, "id"], `duplicate clip id '${c.id}'`);
      ids.add(c.id);
    });
    p.chapters.forEach((ch, i) => {
      if (!ids.has(ch.clipId)) bad(["chapters", i, "clipId"], `chapter points at unknown clip '${ch.clipId}'`);
    });
  });

export type ShortPlan = z.infer<typeof ShortPlanSchema>;
export type ClipPlan = z.infer<typeof ClipSchema>;

export function parsePlan(raw: unknown): ShortPlan {
  const r = ShortPlanSchema.safeParse(raw);
  if (!r.success) {
    const msg = r.error.issues.map((i) => `${i.path.join(".") || "plan"}: ${i.message}`).join("; ");
    throw new Error(`Invalid plan: ${msg}`);
  }
  return r.data;
}

export const dims = (aspect: "9:16" | "16:9") => (aspect === "9:16" ? { W: 1080, H: 1920 } : { W: 1920, H: 1080 });

/** YouTube chapter lines ("0:00 Title"). YouTube needs the first at 0:00, at least 3, each at least 10 seconds. */
export function buildChapters(plan: ShortPlan): string {
  if (plan.chapters.length < 3) return "";
  const starts = new Map<string, number>();
  let t = 0;
  for (const c of plan.clips) {
    starts.set(c.id, t);
    t += c.seconds;
  }
  const items = plan.chapters.map((c) => ({ title: c.title, at: starts.get(c.clipId) ?? 0 })).sort((a, b) => a.at - b.at);
  if (items[0].at !== 0) items.unshift({ title: "Intro", at: 0 });
  const ok = items.every((it, i) => i === 0 || it.at - items[i - 1].at >= 10);
  if (!ok) return "";
  const fmt = (s: number) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, "0")}`;
  return items.map((it) => `${fmt(it.at)} ${it.title}`).join("\n");
}
